SELECT *, (SELECT COUNT(*) FROM shopwizard.tCatCate C WHERE C.ParentCateCode = shopwizard.tCatCate.CateCode) AS ChildCount
FROM shopwizard.tCatCate

    AND SvcCode = #{pSvcCode}


            AND ParentCateCode = #{pParentCateCode}
            AND CateLevel = 0

        AND CateCode = #{pCateCode}


ORDER BY CateSeq, CateCode

SELECT IFNULL(MAX(CateCode),'')
FROM shopwizard.tCatCate

    AND SvcCode = #{svcCode}

        AND ParentCateCode = #{parentCateCode}
        AND CateLevel = 0

    AND DesignId = #{designId}

SELECT *, (SELECT COUNT(*) FROM shopwizard.tCatCate C WHERE C.ParentCateCode = tCatCate.CateCode) AS ChildCount
FROM shopwizard.tCatCate

    AND SvcCode = #{pSvcCode}
    AND ParentCateCode = #{pParentCateCode}
